{"file_path":"/work/tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_an_unconverted_session():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_last_duplicate_wins_before_sorting():
    events = parse_session_log(["b,5,1", "c,1,1", "b,2,0", "a,2,1"])
    assert dedupe_sessions(events) == [events[1], events[3], events[2]]


def test_parse_flags_whitespace_and_skipped_lines():
    assert parse_session_log(["", " \t", "  # comment", " a , 2 , 0 ", " b, 3 , "]) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("line", ["x,2", "x,2,1,extra", "x,not-a-day,0"])
def test_parse_errors_report_input_position(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", "# skipped", "ok,1,1", line])


def test_inclusive_daily_counts_and_trailing_window():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,4,1", "f,5,1"])
    counts = daily_conversion_counts(events, 1, 4)
    assert counts == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 1) == []
    assert conversions_in_window(counts, 3) == 1
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 10) == 3


def test_campaign_summary_weights_sessions_and_counts_calendar_days():
    groups = {"a": parse_session_log(["x,1,1", "y,4,0"]), "b": parse_session_log(["z,1,1"]), "c": []}
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"c": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_order_and_empty_groups():
    groups = {"d": [{"converted": True}], "c": [], "b": [{"converted": False}], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 5) == ["a", "d", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("c", None), ("d", 1.0)]


def test_streak_resets_at_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 1, -1, 2, 1, 1]) == 3
    assert longest_conversion_streak([]) == 0
    assert longest_conversion_streak([-1, 0]) == 0
